{
  "document_metadata": {
    "title": "Taking Marine Mammals Incidental to Construction of the Ocean Wind 1 Offshore Wind Farm Project",
    "document_number": "50 CFR Part 217 Subpart AA",
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Spatial",
      "requirement": "The specified geographical region is the Mid-Atlantic Bight, which includes, but is not limited to, the Bureau of Ocean Energy Management (BOEM) Lease Area Outer Continental Shelf (OCS)-A 0498 Commercial Lease of Submerged Lands for Renewable Energy Development, two export cable routes, and two sea-to-shore transition points located in New Jersey at Oyster Creek, Island Beach State Park in Barnegat Bay, Farm Property, and BL England.",
      "scope": "Mid-Atlantic Bight region, including specific lease areas and cable routes",
      "source": "50 CFR 217.260(b)",
      "related_domains": "Jurisdictional, Environmental"
    },
    {
      "type": "Technical",
      "requirement": "The specified activities are impact pile driving of wind turbine generator (WTGs) and offshore substation (OSSs) foundations; vibratory pile driving (install and subsequently remove) of cofferdams and goal posts; high-resolution geophysical (HRG) site characterization surveys; unexploded ordnances or munitions and explosives of concern (UXOs/MECs) detonation; vessel transit within the specified geographical region to transport crew, supplies, and materials; WTG operation; fishery and ecological monitoring surveys; placement of scour protection; and trenching, laying, and burial activities associated with the installation of the export cable route from OSSs to shore-based converter stations and inter-array cables between turbines.",
      "scope": "All construction and operation activities within the specified geographical region",
      "source": "50 CFR 217.260(c)",
      "related_domains": "Technical, Environmental, Safety"
    }
  ],
  "regulatory_entities": [
    {
      "entity_name": "Bureau of Ocean Energy Management (BOEM)",
      "jurisdiction": "Federal",
      "role": "Lease area management and regulation"
    }
  ]
}

