{
  "document_metadata": {
    "title": "Taking Marine Mammals Incidental to Construction of the Ocean Wind 1...",
    "document_number": "50 CFR Part 217 Subpart AA",
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Safety",
      "requirement": "Prior to the start of all in-water construction activities, the LOA Holder must conduct training for the mammal monitoring team (PSO and PAM operators) to explain responsibilities, communication procedures, marine mammal detection and identification, mitigation, monitoring, and reporting requirements, safety and operational procedures, and authorities of the marine mammal monitoring team(s).",
      "scope": "All in-water construction activities",
      "source": "50 CFR 217.264(a)(2)",
      "related_domains": ["Environmental", "Safety"]
    },
    {
      "type": "Safety",
      "requirement": "The training must be repeated for new personnel who join the work during the project.",
      "scope": "All in-water construction activities",
      "source": "50 CFR 217.264(a)(2)",
      "related_domains": ["Safety"]
    },
    {
      "type": "Safety",
      "requirement": "Prior to and when conducting any in-water activities and vessel operations, LOA Holder personnel and contractors (e.g., vessel operators, PSOs) must use available sources of information on North Atlantic right whale presence in or near the Project Area including daily monitoring of the Right Whale Sightings Advisory System, and monitoring of U.S. Coast Guard VHF Channel 16 throughout the day to receive notification of any sightings and/or information associated with any Slow Zones (i.e., Dynamic Management Areas (DMAs) and/or acoustically-triggered slow zones) to provide situational awareness for both vessel operators, PSO(s), and PAM operator(s).",
      "scope": "All in-water activities and vessel operations",
      "source": "50 CFR 217.264(a)(3)",
      "related_domains": ["Environmental", "Safety"]
    },
    {
      "type": "Safety",
      "requirement": "The marine mammal monitoring team must monitor these systems no less than every 4 hours. For any UXO/MEC detonation, these systems must be monitored for 24 hours and immediately prior to blasting.",
      "scope": "All in-water activities and vessel operations, UXO/MEC detonation",
      "source": "50 CFR 217.264(a)(3)",
      "related_domains": ["Environmental", "Safety"]
    }
  ],
  "regulatory_entities": [
    {
      "entity_name": "NMFS (National Marine Fisheries Service)",
      "jurisdiction": "Federal",
      "role": "Regulatory authority and enforcement"
    },
    {
      "entity_name": "U.S. Coast Guard",
      "jurisdiction": "Federal",
      "role": "Providing information on North Atlantic right whale presence"
    }
  ]
}

