{
  "document_metadata": {
    "title": "North Atlantic Right Whale Vessel Strike Reduction Rule",
    "document_number": null,
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Safety",
      "requirement": "If underway, all vessels must steer a course away from any sighted North Atlantic right whale at 10 kn or less such that the 500-m minimum separation distance requirement is not violated.",
      "scope": "Vessels near North Atlantic right whales",
      "numerical_value": 500,
      "unit": "m",
      "source": "North Atlantic Right Whale Vessel Strike Reduction Rule",
      "related_domains": ["Safety"]
    },
    {
      "type": "Safety",
      "requirement": "If a North Atlantic right whale is sighted within 500 m of an underway vessel, that vessel must reduce speed and shift the engine to neutral. Engines must not be engaged until the whale has moved outside of the vessel's path and beyond 500 m.",
      "scope": "Vessels within 500 m of North Atlantic right whales",
      "numerical_value": 500,
      "unit": "m",
      "source": "North Atlantic Right Whale Vessel Strike Reduction Rule",
      "related_domains": ["Safety"]
    },
    {
      "type": "Safety",
      "requirement": "LOA Holder's vessels must maintain a minimum separation distance of 100 m (328 ft) from sperm whales and non-North Atlantic right whale baleen whales. If one of these species is sighted within 100 m of a transiting vessel, LOA Holder's vessel must reduce speed and shift the engine to neutral. Engines must not be engaged until the whale has moved outside of the vessel's path and beyond 100 m.",
      "scope": "Vessels near sperm whales and non-North Atlantic right whale baleen whales",
      "numerical_value": 100,
      "unit": "m",
      "source": "North Atlantic Right Whale Vessel Strike Reduction Rule",
      "related_domains": ["Safety"]
    },
    {
      "type": "Safety",
      "requirement": "LOA Holder's vessels must maintain a minimum separation distance of 50 m (164 ft) from all delphinoid cetaceans and pinnipeds with an exception made for those that approach the vessel (i.e., bow-riding dolphins). If a delphinid cetacean or pinniped is sighted within 50 m of a transiting vessel, LOA Holder's vessel must shift the engine to neutral, with an exception made for those that approach the vessel (e.g., bow-riding dolphins). Engines must not be engaged until the animal(s) has moved outside of the vessel's path and beyond 50 m.",
      "scope": "Vessels near delphinoid cetaceans and pinnipeds",
